using EventLensAI.Domain.Entities;using EventLensAI.Domain.Enums;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal static class EntitlementSeed{public static readonly DateTime Created=new(2026,7,30,0,0,0,DateTimeKind.Utc);public static Guid Plan(int n)=>Guid.Parse($"70000000-0000-0000-0000-{n:000000000000}");public static Guid Feature(int n)=>Guid.Parse($"71000000-0000-0000-0000-{n:000000000000}");}
internal sealed class EntitlementPlanConfiguration:IEntityTypeConfiguration<EntitlementPlan>{public void Configure(EntityTypeBuilder<EntitlementPlan>b){b.ToTable("subscription_plans");b.ConfigureBase();b.Property(x=>x.Code).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Name).HasMaxLength(100);b.Property(x=>x.Description).HasMaxLength(1000);b.Property(x=>x.MonthlyPrice).HasPrecision(18,2);b.Property(x=>x.YearlyPrice).HasPrecision(18,2);b.HasIndex(x=>x.Code).IsUnique().HasFilter("[IsDeleted] = 0");b.HasIndex(x=>new{x.IsActive,x.DisplayOrder});b.HasData(Row(1,SubscriptionPlan.Free,"Free",0,0,"Essential event tools",3,1,1073741824,1,10,5,100,500,1000),Row(2,SubscriptionPlan.Creator,"Creator",19,190,"For individual creators",25,3,53687091200,25,250,50,5000,10000,10000),Row(3,SubscriptionPlan.Professional,"Professional",49,490,"For professional studios",100,10,214748364800,100,1000,250,25000,50000,100000),Row(4,SubscriptionPlan.Business,"Business",79,790,"For growing agencies",500,25,536870912000,1000,2500,1000,100000,250000,1000000),Row(5,SubscriptionPlan.Enterprise,"Enterprise",299,2990,"Enterprise scale and governance",10000,1000,2199023255552,100000,25000,10000,1000000,5000000,10000000),Row(6,SubscriptionPlan.CustomEnterprise,"Custom Enterprise",0,0,"Contract-defined limits",-1,-1,-1,-1,-1,-1,-1,-1,-1));}private static object Row(int id,SubscriptionPlan code,string name,decimal monthly,decimal yearly,string description,int events,int members,long storage,int galleries,int ai,int templates,int uploads,int captures,int api)=>new{Id=EntitlementSeed.Plan(id),Code=code,Name=name,MonthlyPrice=monthly,YearlyPrice=yearly,Description=description,IsActive=true,DisplayOrder=id,MaximumEvents=events,MaximumTeamMembers=members,MaximumStorage=storage,MaximumGalleries=galleries,MaximumAIJobs=ai,MaximumTemplates=templates,MaximumUploads=uploads,MaximumMonthlyCaptures=captures,MaximumApiRequests=api,CreatedAt=EntitlementSeed.Created,UpdatedAt=(DateTime?)null,CreatedBy=(Guid?)null,UpdatedBy=(Guid?)null,IsDeleted=false};}
internal sealed class FeatureDefinitionConfiguration:IEntityTypeConfiguration<FeatureDefinition>{public void Configure(EntityTypeBuilder<FeatureDefinition>b){b.ToTable("feature_definitions");b.ConfigureBase();b.Property(x=>x.Key).HasMaxLength(100);b.Property(x=>x.Name).HasMaxLength(100);b.Property(x=>x.Description).HasMaxLength(500);b.HasIndex(x=>x.Key).IsUnique().HasFilter("[IsDeleted] = 0");var n=0;b.HasData(EntitlementFeatures.All.Select(k=>new{Id=EntitlementSeed.Feature(++n),Key=k,Name=string.Join(' ',k.Split('.').Select(x=>char.ToUpperInvariant(x[0])+x[1..])),Description=$"Controls access to {k}.",CreatedAt=EntitlementSeed.Created,UpdatedAt=(DateTime?)null,CreatedBy=(Guid?)null,UpdatedBy=(Guid?)null,IsDeleted=false}));}}
internal sealed class PlanFeatureConfiguration:IEntityTypeConfiguration<PlanFeature>{public void Configure(EntityTypeBuilder<PlanFeature>b){b.ToTable("plan_features");b.ConfigureBase();b.HasIndex(x=>new{x.PlanId,x.FeatureId}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne(x=>x.Plan).WithMany(x=>x.Features).HasForeignKey(x=>x.PlanId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.Feature).WithMany().HasForeignKey(x=>x.FeatureId).OnDelete(DeleteBehavior.NoAction);var rows=new List<object>();var id=1;for(var p=1;p<=6;p++)for(var f=1;f<=EntitlementFeatures.All.Length;f++){var enabled=p switch{1=>f is 4 or 6 or 16 or 17,2=>f is not(1 or 2 or 11 or 12 or 13 or 18),3=>f is not(1 or 2 or 12 or 13),4=>f is not(1 or 2 or 12),_=>true};rows.Add(new{Id=Guid.Parse($"72000000-0000-0000-0000-{id++:000000000000}"),PlanId=EntitlementSeed.Plan(p),FeatureId=EntitlementSeed.Feature(f),Enabled=enabled,CreatedAt=EntitlementSeed.Created,UpdatedAt=(DateTime?)null,CreatedBy=(Guid?)null,UpdatedBy=(Guid?)null,IsDeleted=false});}b.HasData(rows);}}
internal sealed class OrganizationSubscriptionConfiguration:IEntityTypeConfiguration<OrganizationSubscription>{public void Configure(EntityTypeBuilder<OrganizationSubscription>b){b.ToTable("organization_subscriptions");b.ConfigureBase();b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(20);b.HasIndex(x=>new{x.OrganizationId,x.Status});b.HasOne(x=>x.Organization).WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.Plan).WithMany().HasForeignKey(x=>x.PlanId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class UsageRecordConfiguration:IEntityTypeConfiguration<UsageRecord>{public void Configure(EntityTypeBuilder<UsageRecord>b){b.ToTable("entitlement_usage_records");b.ConfigureBase();b.Property(x=>x.Metric).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Reference).HasMaxLength(200);b.HasIndex(x=>new{x.OrganizationId,x.Metric,x.OccurredAt});b.HasIndex(x=>new{x.OrganizationId,x.Reference});}}
